import zipfile, re, sys, xml.etree.ElementTree as ET

NS = '{http://schemas.openxmlformats.org/spreadsheetml/2006/main}'
RNS = '{http://schemas.openxmlformats.org/officeDocument/2006/relationships}'

def col_idx(ref):
    m = re.match(r'([A-Z]+)', ref)
    n = 0
    for c in m.group(1):
        n = n * 26 + (ord(c) - 64)
    return n - 1

def load(path):
    z = zipfile.ZipFile(path)
    shared = []
    if 'xl/sharedStrings.xml' in z.namelist():
        root = ET.fromstring(z.read('xl/sharedStrings.xml'))
        for si in root:
            shared.append(''.join(t.text or '' for t in si.iter(NS+'t')))
    wb = ET.fromstring(z.read('xl/workbook.xml'))
    rels = {r.get('Id'): r.get('Target') for r in ET.fromstring(z.read('xl/_rels/workbook.xml.rels'))}
    sheets = []
    for sh in wb.iter(NS+'sheet'):
        target = rels[sh.get(RNS+'id')]
        if not target.startswith('xl/'):
            target = 'xl/' + target.lstrip('/')
        sheets.append((sh.get('name'), target))
    out = {}
    for name, target in sheets:
        root = ET.fromstring(z.read(target))
        rows = []
        for row in root.iter(NS+'row'):
            cells = {}
            for c in row.iter(NS+'c'):
                v = c.find(NS+'v')
                t = c.get('t')
                if t == 'inlineStr':
                    isel = c.find(NS+'is')
                    val = ''.join(x.text or '' for x in isel.iter(NS+'t')) if isel is not None else ''
                elif v is None:
                    continue
                elif t == 's':
                    val = shared[int(v.text)]
                else:
                    val = v.text
                if val is None or val == '':
                    continue
                cells[col_idx(c.get('r'))] = val.strip()
            if cells:
                rows.append((int(row.get('r')), cells))
        out[name] = rows
    return out

if __name__ == '__main__':
    data = load(sys.argv[1])
    for name, rows in data.items():
        print('=== SHEET:', name, '| rows:', len(rows))
        maxr = int(sys.argv[2]) if len(sys.argv) > 2 else 40
        for rn, cells in rows[:maxr]:
            width = max(cells) + 1
            print(rn, ' | '.join(cells.get(i, '') for i in range(width)))

