/**
 * Indicizza i tag dell'anagrafica tessuti Indoor per categoria e nome
 * normalizzato. Se l'anagrafica non è stata importata l'indice resta vuoto
 * e i tag del file finiscono tutti fra gli sconosciuti: l'avviso a fine run
 * dice cosa manca.
 */
private function loadTagIndex(): void
{
    $categories = TagCategory::query()
        ->whereIn('slug', array_values(self::TAG_COLUMNS))
        ->whereHas('group', fn ($q) => $q->where('entity_type', 'fabric'))
        ->pluck('slug', 'id');

    if ($categories->isEmpty()) {
        return;
    }

    foreach (Tag::query()->whereIn('tag_category_id', $categories->keys())->get() as $tag) {
        $slug = $categories[$tag->tag_category_id];
        $this->tagIndex[$slug][$this->normalize($tag->name)] = $tag->id;
    }
}

