/**
 * Congiunzioni e preposizioni che restano minuscole dentro il nome: in
 * italiano "Teli Di Copertura" non si scrive. In prima posizione la
 * maiuscola la prendono comunque.
 *
 * @var list<string>
 */
private const LOWERCASE_WORDS = [
    'a', 'al', 'con', 'da', 'dei', 'del', 'della', 'delle', 'di', 'e',
    'ed', 'il', 'in', 'la', 'le', 'lo', 'per', 'su', 'un', 'una',
];

/**
 * Iniziale maiuscola su ogni parola, escluse le paroline funzionali. Il
 * file scrive le categorie con casing incoerente ("Tessuto york" accanto a
 * "Tessuto Velluto", "Pelle soft Grain"): le costanti lo conservano per
 * restare confrontabili col file, ma in admin le tipologie devono leggersi
 * uniformi.
 *
 * Vale solo sull'italiano, che viene dal file; l'EN è curato a mano.
 */
private function titleCase(string $value): string
{
    $words = preg_split('/\s+/u', trim($value)) ?: [];

    foreach ($words as $i => $word) {
        $lower = mb_strtolower($word, 'UTF-8');

        $words[$i] = $i > 0 && in_array($lower, self::LOWERCASE_WORDS, true)
            ? $lower
            : mb_convert_case($word, MB_CASE_TITLE, 'UTF-8');
    }

    return implode(' ', $words);
}

