                $raw = $cell?->getValue();
                $value = is_scalar($raw) ? trim((string) $raw) : '';

                if ($value === '') {
                    continue;
                }

                $blockName = self::BLOCKS[$this->normalize($value)] ?? null;
                if ($blockName !== null) {
                    $current = $blockName;
                    $blocks[$current] ??= [];

                    continue;
                }

                if ($current === null) {
                    $this->warn("Valore fuori da ogni blocco, ignorato: {$value}");

                    continue;
                }

                $color = $rowColors[$rowNumber] ?? null;
                $rowValues = $current === self::COMMA_SEPARATED_BLOCK
                    ? array_values(array_filter(array_map(trim(...), explode(',', $value)), fn (string $v): bool => $v !== ''))
                    : [$value];
                foreach ($rowValues as $rowValue) {
                    $blocks[$current][] = ['value' => $rowValue, 'color' => $color];
                }
            }

            break;
        }
        $reader->close();

        return $blocks;
    }

    /**
     * Gruppo tag anagrafica dei materiali Outdoor (creato se assente, come la
     * Category1 "Outdoor").
     */

