48	{
49	    protected $signature = 'app:import-filtri-interior '
50	        . '{--file=storage/app/private/import/2026-07-21/INTERIOR - materiali e tessuti filtri-mappatura.xlsx} '
51	        . '{--fresh : Svuota i tag delle categorie interessate prima di reimportare}';
52	
53	    protected $description = 'Import dei tag anagrafica Interior (materiali + tessuti) dal file filtri';
54	
55	    private const SHEET_MATERIALS = 'Materiali';
56	
57	    private const SHEET_FABRICS = 'Tessuti';
58	
59	    /** Colonna con lo sfondo colorato accanto ai valori del blocco "Colori". */
60	    private const COLOR_COLUMN = 'B';
61	
62	    /**
63	     * Blocchi del foglio Materiali (chiave normalizzata) → nome della
64	     * TagCategory. Nel foglio compaiono con casing misto (es. "FINITURA").
65	     *
66	     * @var array<string, string>
67	     */
68	    private const MATERIAL_BLOCKS = [
69	        'tipologia' => 'Tipologia',
70	        'finitura' => 'Finitura',
71	        'colore' => 'Colore',
72	    ];
73	
74	    /**
75	     * Blocchi del foglio Tessuti dichiarati TAG → slug stabile e nome della
76	     * TagCategory.
77	     *
78	     * @var array<string, array{slug: string, name: string}>
79	     */
80	    private const FABRIC_BLOCKS = [
81	        'tipologia' => ['slug' => 'tipologia', 'name' => 'Tipologia'],
82	        'colori' => ['slug' => 'colori', 'name' => 'Colori'],
83	        'pattern' => ['slug' => 'pattern', 'name' => 'Pattern'],
84	    ];
85	
86	    /**
87	     * Blocchi del foglio Tessuti dichiarati PROPRIETÀ: sono colonne di
88	     * `fabrics`, non tag. Vanno comunque riconosciuti come intestazioni,
89	     * altrimenti i loro valori finirebbero nel blocco tag precedente.
90	     *
91	     * @var list<string>
92	     */
93	    private const FABRIC_PROPERTY_BLOCKS = ['proprietà', 'costo', 'moodboard', 'categoria'];
94	
95	    /**
96	     * TagCategory tessuto create dalle versioni precedenti del file e non più
97	     * previste: "Tipo disegno" è stato rinominato "Pattern", gli altri tre
98	     * blocchi sono diventati proprietà.
99	     *
100	     * @var list<string>
101	     */
102	    private const FABRIC_OBSOLETE_CATEGORIES = ['tipo-disegno', 'proprieta', 'categoria', 'moodboard'];
103	
104	    public function handle(): int
105	    {
106	        $file = (string) $this->option('file');
107	        if (! is_file($file)) {
108	            $this->error("File non trovato: {$file}");
109	
110	            return self::FAILURE;
111	        }
112	
113	        // la destinazione è un presupposto della tassonomia, non un dato da
114	        // importare: se manca la si crea, così il comando non dipende da un
115	        // seeder lanciato prima
116	        $indoor = Category1::query()->firstOrCreate(
117	            ['slug' => 'indoor'],
118	            ['name' => ['it' => 'Interior', 'en' => 'Interior']],
119	        );
120	
121	        $materialBlocks = $this->parseMaterialSheet($file);
122	        $fabricBlocks = $this->parseFabricSheet($file);
123	
124	        if ($materialBlocks === null && $fabricBlocks === null) {
125	            $this->error('Nessuno dei due fogli ("' . self::SHEET_MATERIALS . '", "' . self::SHEET_FABRICS . '") trovato nel file.');
126	
127	            return self::FAILURE;
128	        }
129	
130	        $stats = [
131	            'material categories' => 0, 'material tags' => 0, 'materials tagged' => 0,
132	            'fabric categories' => 0, 'fabric tags' => 0, 'swatches' => 0,
133	            'obsolete' => 0, 'pruned' => 0,
134	        ];
135	
136	        DB::transaction(function () use ($indoor, $materialBlocks, $fabricBlocks, &$stats): void {
137	            if ($materialBlocks !== null) {
138	                $this->importMaterialTags($indoor, $materialBlocks, $stats);
